WITH exploded AS (SELECT id, plan, effective_from, val FROM price_tiers LATERAL VIEW EXPLODE(discounts) e AS val), scored AS (SELECT *, MAX(val) OVER (PARTITION BY plan) AS plan_max_val, DENSE_RANK() OVER (PARTITION BY plan ORDER BY val ASC NULLS LAST) AS val_dense_rank FROM exploded), base AS (SELECT *, ROUND(plan_max_val, 1) AS plan_max_val_rounded FROM scored WHERE MONTH(effective_from) IN (3, 4, 5)), remaining_keys AS (SELECT plan, id FROM base EXCEPT SELECT plan, id FROM price_tiers WHERE currency <> 'USD'), verified AS (SELECT s.* FROM base s INNER JOIN remaining_keys k ON s.plan = k.plan AND s.id = k.id), cleaned AS (SELECT *, COALESCE(val, 0) AS val_filled, val_dense_rank - plan_max_val AS val_dense_rank_minus_plan_max_val FROM verified WHERE plan_max_val_rounded IS NOT NULL), base_price_tiers AS (SELECT *, plan_max_val_rounded * plan_max_val AS plan_max_val_rounded_times_plan_max_val, TRIM(plan) AS clean_plan FROM cleaned WHERE effective_from >= DATE '2024-01-31' AND plan_max_val_rounded BETWEEN 23 AND 77) SELECT id, plan, effective_from, val, val_dense_rank, plan_max_val_rounded, val_filled, val_dense_rank_minus_plan_max_val, plan_max_val_rounded_times_plan_max_val, CASE WHEN plan RLIKE '^(enterprise|starter)$' THEN 'GROUP_B' WHEN plan RLIKE '^(basic|pro)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS plan_zone FROM base_price_tiers
